SELECT NotaDePedido.Anulado, NotaDePedido.MotivoAnulado, cfechasqlfecha([NotaDePedido]![Fecha]) AS Fecha, cfechasqlhora([NotaDePedido]![Hora]) AS Hora, NotaDePedido.CodPedido, NotaDePedido.CodCliente, IIf([NotaDePedido]![POS]=-1,"A Cuentas","Efectivo") AS aPOS, [Delivery]![Nombre] AS Delivery_Nombre, Grupos.Tipo, Grupos.NombreGrupo, [DBBatidos]![Nombre] AS DBBatidos_Nombre, DBBatidos.Medida, SubPedido.Cantidad, [SubPedido]![CodPromocion] AS CodigoPromocion, [SubPedido]![Cantidad]*PrecioReal([SubPedido]![CodSubPedido]) AS Precio, codigolocal() AS [local], IIf(OperarioCaja([NotaDePedido]![Hora],[NotaDePedido]![Fecha])="No Registrado",[Formularios]![Main Pitaya]![usuariologin],OperarioCaja([NotaDePedido]![Hora],[NotaDePedido]![Fecha])) AS Caja, statusnotaddepedido([NotaDePedido]![CodPedido]) AS Modalidad, IIf(IsNull([NotaDePedido]![CodMotorizado]),"",NombreOperario([NotaDePedido]![CodMotorizado])) AS Motorizado, SubPedido.Observaciones, IIf([SubPedido]![CodPromocion]=92,0,IIf([SubPedido]![CodPromocion]=104,0,[DBBatidos]![Precio])) AS Precio_Unitario_Sin_Descuento, NotaDePedido.Impresiones, cfechasqlhora([NotaDePedido]![HoraCreado]) AS HoraCreado, cfechasqlhora([NotaDePedido]![HoraIngresoProducto]) AS HoraIngresoProducto, cfechasqlhora([NotaDePedido]![HoraImpreso]) AS HoraImpreso, NotaDePedido.Propina, numerosemana([NotaDePedido]![Fecha]) AS semana, SubPedido.Puntos, [SubPedido]![CodBatido] AS CodProducto, [NotaDePedido]![TotalGuardado] AS MontoFactura, nombrelocalglobal(codigolocal()) AS Sucursal_Nombre, IIf(DCount("*","[StatusPedidosCentral]","[CodPedidoSucursal] = " & [NotaDePedido]![CodPedido])>0,1,0) AS PedidoDeCentral, NotaDePedido.CodMotorizado
FROM ((Delivery INNER JOIN ((SubPedido INNER JOIN DBBatidos ON SubPedido.CodBatido = DBBatidos.CodBatido) INNER JOIN NotaDePedido ON SubPedido.CodPedido = NotaDePedido.CodPedido) ON Delivery.CodDelivery = NotaDePedido.Delivery) INNER JOIN DBPromociones ON SubPedido.CodPromocion = DBPromociones.CodPromocion) INNER JOIN Grupos ON DBBatidos.CodGrupo = Grupos.CodGrupo;

